 1922: u64 gf_m2ts_get_pts(unsigned char *data)
 1923: {
 1924: 	u64 pts;
 1925: 	u32 val;
 1926: 	pts = (u64)((data[0] >> 1) & 0x07) << 30;
 1927: 	val = (data[1] << 8) | data[2];
 1928: 	pts |= (u64)(val >> 1) << 15;
 1929: 	val = (data[3] << 8) | data[4];
 1930: 	pts |= (u64)(val >> 1);
 1931: 	return pts;
 1932: }
