 3190: static Bool gf_m2ts_probe_buffer(char *buf, u32 size)
 3191: {
 3192: 	GF_Err e;
 3193: 	GF_M2TS_Demuxer *ts;
 3194: 	u32 lt;
 3195: 
 3196: 	lt = gf_log_get_tool_level(GF_LOG_CONTAINER);
 3197: 	gf_log_set_tool_level(GF_LOG_CONTAINER, GF_LOG_QUIET);
 3198: 
 3199: 	ts = gf_m2ts_demux_new();
 3200: 	e = gf_m2ts_process_data(ts, buf, size);
 3201: 
 3202: 	if (!ts->pck_number) {
 3203: 		e = GF_BAD_PARAM;
 3204: 	} else {
 3205: 		u32 nb_pck;
 3206: 		//max number of packets
 3207: 		if (ts->prefix_present)
 3208: 			nb_pck = size/192;
 3209: 		else
 3210: 			nb_pck = size/188;
 3211: 		//incomplete last packet
 3212: 		if (ts->buffer_size) nb_pck--;
 3213: 		//probe success if after align we have nb_pck - 2 and at least 2 packets
 3214: 		if ((nb_pck<2) || (ts->pck_number + 2 < nb_pck))
 3215: 			e = GF_BAD_PARAM;
 3216: 	}
 3217: 	gf_m2ts_demux_del(ts);
 3218: 
 3219: 	gf_log_set_tool_level(GF_LOG_CONTAINER, lt);
 3220: 
 3221: 	if (e) return GF_FALSE;
 3222: 	return GF_TRUE;
 3223: 
 3224: }
