  649: static void m2tdmx_merge_props(GF_FilterPid *pid, GF_M2TS_ES *stream, GF_FilterPacket *pck)
  650: {
  651: 	if (stream->props) {
  652: 		char szID[100];
  653: 		while (gf_list_count(stream->props)) {
  654: 			GF_M2TS_Prop *p = gf_list_pop_front(stream->props);
  655: 			switch(p->type) {
  656: 				case M2TS_TEMI_INFO: {
  657: 					GF_M2TS_Prop_TEMIInfo *t = (GF_M2TS_Prop_TEMIInfo*)p;
  658: 					snprintf(szID, 100, "%s:%d", t->is_loc ? "temi_l" : "temi_t", t->timeline_id);
  659: 					break;
  660: 				}
  661: 				case M2TS_SCTE35:
  662: 					snprintf(szID, 100, "scte35");
  663: 					break;
  664: 				case M2TS_ID3:
  665: 					snprintf(szID, 100, "id3");
  666: 					break;
  667: 				default:
  668: 					GF_LOG(GF_LOG_ERROR, GF_LOG_CONTAINER, ("[M2TSDmx] unknown property %d - skipping\n", p->type) );
  669: 					gf_free(p);
  670: 					continue;
  671: 			}
  672: 
  673: 			gf_filter_pck_set_property_dyn(pck, szID, &PROP_DATA_NO_COPY(p->data, p->len));
  674: 			gf_free(p);
  675: 		}
  676: 		gf_list_del(stream->props);
  677: 		stream->props = NULL;
  678: 
  679: 		if (!(stream->flags & GF_M2TS_ES_TEMI_INFO)) {
  680: 			stream->flags |= GF_M2TS_ES_TEMI_INFO;
