 2733: GF_Err gf_m2ts_process_data(GF_M2TS_Demuxer *ts, u8 *data, u32 data_size)
 2734: {
 2735: 	GF_Err e=GF_OK;
 2736: 	u32 pos, pck_size;
 2737: 	Bool is_align = 1;
 2738: 
 2739: 	if (ts->buffer_size) {
 2740: 		//we are sync, copy remaining bytes
 2741: 		if ( (ts->buffer[0]==0x47) && (ts->buffer_size<200)) {
 2742: 			u32 copy_size;
 2743: 			pck_size = ts->prefix_present ? 192 : 188;
 2744: 
 2745: 			if (ts->alloc_size < 200) {
 2746: 				ts->alloc_size = 200;
 2747: 				ts->buffer = (char*)gf_realloc(ts->buffer, sizeof(char)*ts->alloc_size);
 2748: 			}
 2749: 			copy_size = pck_size - ts->buffer_size;
 2750: 			if (copy_size > data_size) {
 2751: 				memcpy(ts->buffer + ts->buffer_size, data, data_size);
 2752: 				ts->buffer_size += data_size;
 2753: 				return GF_OK;
 2754: 			}
 2755: 			memcpy(ts->buffer + ts->buffer_size, data, copy_size);
 2756: 			e |= gf_m2ts_process_packet(ts, (unsigned char *)ts->buffer);
 2757: 			data += copy_size;
 2758: 			data_size = data_size - copy_size;
 2759: 			gf_assert((s32)data_size >= 0);
 2760: 		}
 2761: 		//not sync, copy over the complete buffer
 2762: 		else {
 2763: 			if (ts->alloc_size < ts->buffer_size+data_size) {
 2764: 				ts->alloc_size = ts->buffer_size+data_size;
 2765: 				ts->buffer = (char*)gf_realloc(ts->buffer, sizeof(char)*ts->alloc_size);
 2766: 			}
 2767: 			memcpy(ts->buffer + ts->buffer_size, data, sizeof(char)*data_size);
 2768: 			ts->buffer_size += data_size;
 2769: 			is_align = 0;
 2770: 			data = ts->buffer;
 2771: 			data_size = ts->buffer_size;
 2772: 		}
 2773: 	}
 2774: 
 2775: 	/*sync input data*/
 2776: 	pos = gf_m2ts_sync(ts, data, data_size, is_align);
 2777: 	if (pos==data_size) {
 2778: 		if (is_align) {
 2779: 			if (ts->alloc_size<data_size) {
 2780: 				ts->buffer = (char*)gf_realloc(ts->buffer, sizeof(char)*data_size);
 2781: 				ts->alloc_size = data_size;
 2782: 			}
 2783: 			memcpy(ts->buffer, data, sizeof(char)*data_size);
 2784: 			ts->buffer_size = data_size;
 2785: 		}
 2786: 		return GF_OK;
 2787: 	}
 2788: 	pck_size = ts->prefix_present ? 192 : 188;
 2789: 	for (;;) {
 2790: 		/*wait for a complete packet*/
 2791: 		if (data_size < pos  + pck_size) {
 2792: 			ts->buffer_size = data_size - pos;
 2793: 			data += pos;
 2794: 			if (!ts->buffer_size) {
 2795: 				return e;
 2796: 			}
 2797: 			gf_assert(ts->buffer_size<pck_size);
 2798: 
 2799: 			if (is_align) {
 2800: 				u32 s = ts->buffer_size;
 2801: 				if (s<200) s = 200;
 2802: 
 2803: 				if (ts->alloc_size < s) {
 2804: 					ts->alloc_size = s;
 2805: 					ts->buffer = (char*)gf_realloc(ts->buffer, sizeof(char)*ts->alloc_size);
 2806: 				}
 2807: 				memcpy(ts->buffer, data, sizeof(char)*ts->buffer_size);
 2808: 			} else {
 2809: 				memmove(ts->buffer, data, sizeof(char)*ts->buffer_size);
 2810: 			}
 2811: 			return e;
 2812: 		}
 2813: 		/*process*/
 2814: 		GF_Err pck_e = gf_m2ts_process_packet(ts, (unsigned char *)data + pos);
 2815: 		if (pck_e==GF_NOT_SUPPORTED) pck_e = GF_OK;
 2816: 		e |= pck_e;
 2817: 
 2818: 		pos += pck_size;
 2819: 	}
 2820: 	return e;
 2821: }
