  110: static void m2tsdmx_estimate_duration(GF_M2TSDmxCtx *ctx, GF_M2TS_ES *stream)
  111: {
  112: 	Bool changed;
  113: 	Double pck_dur;
  114: 	const GF_PropertyValue *p;
  115: 
  116: 	if (ctx->duration.num) return;
  117: 	if (!ctx->file_size) {
  118: 		p = gf_filter_pid_get_property(ctx->ipid, GF_PROP_PID_DOWN_SIZE);
  119: 		if (p) {
  120: 			ctx->file_size = p->value.longuint;
--- /workspace/repo-vul/src-vul/gpac/src/filters/dmx_m2ts.c:120-260 ---
  120: 			ctx->file_size = p->value.longuint;
  121: 		} else {
  122: 			ctx->duration.num = 1;
  123: 			return;
  124: 		}
  125: 	}
  126: 
  127: 	if (!ctx->first_pcr_found) {
  128: 		ctx->first_pcr_found = stream->program->last_pcr_value;
  129: 		ctx->pcr_pid = stream->pid;
  130: 		ctx->nb_pck_at_pcr = ctx->ts->pck_number;
  131: 		return;
  132: 	}
  133: 	if (ctx->pcr_pid != stream->pid) return;
  134: 	if (stream->program->last_pcr_value < ctx->first_pcr_found) {
  135: 		ctx->first_pcr_found = stream->program->last_pcr_value;
  136: 		ctx->pcr_pid = stream->pid;
  137: 		ctx->nb_pck_at_pcr = ctx->ts->pck_number;
  138: 		return;
  139: 	}
  140: 	if (stream->program->last_pcr_value - ctx->first_pcr_found <= 2*27000000)
  141: 		return;
  142: 
  143: 	changed = GF_FALSE;
  144: 
  145: 	pck_dur = (Double) (stream->program->last_pcr_value - ctx->first_pcr_found);
  146: 	pck_dur /= (ctx->ts->pck_number - ctx->nb_pck_at_pcr);
  147: 	pck_dur /= 27000;
  148: 
  149: 	pck_dur *= ctx->file_size;
  150: 	pck_dur /= ctx->ts->prefix_present ? 192 : 188;
  151: 	if ((u32) ctx->duration.num != (u32) pck_dur) {
  152: 		ctx->duration.num = (s32) pck_dur;
  153: 		ctx->duration.den = 1000;
  154: 		changed = GF_TRUE;
  155: 	}
  156: 	ctx->first_pcr_found = stream->program->last_pcr_value;
  157: 	ctx->pcr_pid = stream->pid;
  158: 	ctx->nb_pck_at_pcr = ctx->ts->pck_number;
  159: 	GF_LOG(GF_LOG_DEBUG, GF_LOG_CONTAINER, ("[M2TSDmx] Estimated duration based on instant bitrate: %g sec\n", pck_dur/1000));
  160: 
  161: 	if (changed) {
  162: 		u32 i, nb_streams = gf_filter_get_opid_count(ctx->filter);
  163: 		for (i=0; i<nb_streams; i++) {
  164: 			GF_FilterPid *opid = gf_filter_get_opid(ctx->filter, i);
  165: 			gf_filter_pid_set_property(opid, GF_PROP_PID_DURATION, &PROP_FRAC64(ctx->duration) );
  166: 		}
  167: 	}
  168: }
