 3102: GF_EXPORT
 3103: void gf_m2ts_demux_del(GF_M2TS_Demuxer *ts)
 3104: {
 3105: 	u32 i;
 3106: 	if (ts->pat) gf_m2ts_section_filter_del(ts->pat);
 3107: 	if (ts->cat) gf_m2ts_section_filter_del(ts->cat);
 3108: 	if (ts->sdt) gf_m2ts_section_filter_del(ts->sdt);
 3109: 	if (ts->nit) gf_m2ts_section_filter_del(ts->nit);
 3110: 	if (ts->eit) gf_m2ts_section_filter_del(ts->eit);
 3111: 	if (ts->tdt_tot) gf_m2ts_section_filter_del(ts->tdt_tot);
 3112: 
 3113: 	for (i=0; i<GF_M2TS_MAX_STREAMS; i++) {
 3114: 		//because of pure PCR streams, an ES might be reassigned on 2 PIDs, one for the ES and one for the PCR
 3115: 		if (ts->ess[i] && (ts->ess[i]->pid==i)) {
 3116: 			gf_m2ts_es_del(ts->ess[i], ts);
 3117: 		}
 3118: 	}
 3119: 	if (ts->buffer) gf_free(ts->buffer);
 3120: 	while (gf_list_count(ts->programs)) {
 3121: 		GF_M2TS_Program *p = (GF_M2TS_Program *)gf_list_last(ts->programs);
 3122: 		gf_list_rem_last(ts->programs);
 3123: 
 3124: 		while (gf_list_count(p->streams)) {
 3125: 			GF_M2TS_ES *es = (GF_M2TS_ES *)gf_list_last(p->streams);
 3126: 			gf_list_rem_last(p->streams);
 3127: 			//force destroy
 3128: 			es->flags &= ~GF_M2TS_ES_IS_PCR_REUSE;
 3129: 			gf_m2ts_es_del(es, ts);
 3130: 		}
 3131: 		gf_list_del(p->streams);
 3132: 		/*reset OD list*/
 3133: 		if (p->additional_ods) {
 3134: 			gf_odf_desc_list_del(p->additional_ods);
 3135: 			gf_list_del(p->additional_ods);
 3136: 		}
 3137: 		if (p->pmt_iod) gf_odf_desc_del((GF_Descriptor *)p->pmt_iod);
 3138: 		if (p->metadata_pointer_descriptor)	gf_m2ts_metadata_pointer_descriptor_del(p->metadata_pointer_descriptor);
 3139: 		gf_free(p);
 3140: 	}
 3141: 	gf_list_del(ts->programs);
 3142: 
 3143: 	if (ts->TDT_time) gf_free(ts->TDT_time);
 3144: 	gf_m2ts_reset_sdt(ts);
 3145: 	if (ts->tdt_tot)
 3146: 		gf_list_del(ts->SDTs);
 3147: 
 3148: #ifdef GPAC_ENABLE_MPE
 3149: 	gf_dvb_mpe_shutdown(ts);
 3150: #endif
 3151: 
 3152: 	if (ts->dsmcc_controler) {
 3153: 		if (gf_list_count(ts->dsmcc_controler)) {
 3154: #ifdef GPAC_ENABLE_DSMCC
 3155: 			GF_M2TS_DSMCC_OVERLORD* dsmcc_overlord = (GF_M2TS_DSMCC_OVERLORD*)gf_list_get(ts->dsmcc_controler,0);
 3156: 			gf_dir_cleanup(dsmcc_overlord->root_dir);
 3157: 			gf_rmdir(dsmcc_overlord->root_dir);
 3158: 			gf_m2ts_delete_dsmcc_overlord(dsmcc_overlord);
 3159: 			if(ts->dsmcc_root_dir) {
 3160: 				gf_free(ts->dsmcc_root_dir);
 3161: 			}
 3162: #endif
 3163: 		}
 3164: 		gf_list_del(ts->dsmcc_controler);
 3165: 	}
 3166: 
 3167: 	while(gf_list_count(ts->ChannelAppList)) {
 3168: #ifdef GPAC_ENABLE_DSMCC
 3169: 		GF_M2TS_CHANNEL_APPLICATION_INFO* ChanAppInfo = (GF_M2TS_CHANNEL_APPLICATION_INFO*)gf_list_get(ts->ChannelAppList,0);
 3170: 		gf_m2ts_delete_channel_application_info(ChanAppInfo);
 3171: 		gf_list_rem(ts->ChannelAppList,0);
 3172: #endif
 3173: 	}
 3174: 	gf_list_del(ts->ChannelAppList);
 3175: 
 3176: 	if (ts->dsmcc_root_dir) gf_free(ts->dsmcc_root_dir);
 3177: 	gf_free(ts);
 3178: }
